import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"52、【艮】 艮下艮上","description":"温公易说 - 52、【艮】 艮下艮上","frontmatter":{"title":"52、【艮】 艮下艮上","description":"温公易说 - 52、【艮】 艮下艮上"},"headers":[],"relativePath":"zh/classics/wengong/053.md","filePath":"zh/classics/wengong/053.md"}'),n={name:"zh/classics/wengong/053.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_52、【艮】-艮下艮上" tabindex="-1">52、【艮】 艮下艮上 <a class="header-anchor" href="#_52、【艮】-艮下艮上" aria-label="Permalink to “52、【艮】 艮下艮上”">​</a></h1><h3 id="彖曰-艮-止也。时止则止-时行则行。动静不失其时-其道光明。艮其止-止其所也。上下敌应-不相与也-是以不获其身-行其庭-不见其人-无咎也。" tabindex="-1">彖曰：艮，止也。时止则止，时行则行。动静不失其时，其道光明。艮其止，止其所也。上下敌应，不相与也，是以不获其身，行其庭，不见其人，无咎也。 <a class="header-anchor" href="#彖曰-艮-止也。时止则止-时行则行。动静不失其时-其道光明。艮其止-止其所也。上下敌应-不相与也-是以不获其身-行其庭-不见其人-无咎也。" aria-label="Permalink to “彖曰：艮，止也。时止则止，时行则行。动静不失其时，其道光明。艮其止，止其所也。上下敌应，不相与也，是以不获其身，行其庭，不见其人，无咎也。”">​</a></h3><h3 id="象曰-兼山-艮。君子以思不出其位。" tabindex="-1">象曰：兼山，艮。君子以思不出其位。 <a class="header-anchor" href="#象曰-兼山-艮。君子以思不出其位。" aria-label="Permalink to “象曰：兼山，艮。君子以思不出其位。”">​</a></h3><h3 id="初六-艮其趾-无咎-利永贞-象曰-艮其趾-未失正也。" tabindex="-1">初六：艮其趾，无咎，利永贞 象曰：艮其趾，未失正也。 <a class="header-anchor" href="#初六-艮其趾-无咎-利永贞-象曰-艮其趾-未失正也。" aria-label="Permalink to “初六：艮其趾，无咎，利永贞 象曰：艮其趾，未失正也。”">​</a></h3><p>其位则下，其事则初，止而不行，何咎之有？抑君子于其所止，不可不谨择也。止于永贞，利莫大焉。</p><h3 id="六二-艮其腓-不拯其随-其心不快-象曰-不拯其随-未退听也。" tabindex="-1">六二：艮其腓，不拯其随，其心不快 象曰：不拯其随，未退听也。 <a class="header-anchor" href="#六二-艮其腓-不拯其随-其心不快-象曰-不拯其随-未退听也。" aria-label="Permalink to “六二：艮其腓，不拯其随，其心不快 象曰：不拯其随，未退听也。”">​</a></h3><h3 id="九三-艮其限-列其夤-厉熏心-象曰-艮其限-危熏心也。" tabindex="-1">九三：艮其限，列其夤，厉熏心 象曰：艮其限，危熏心也。 <a class="header-anchor" href="#九三-艮其限-列其夤-厉熏心-象曰-艮其限-危熏心也。" aria-label="Permalink to “九三：艮其限，列其夤，厉熏心 象曰：艮其限，危熏心也。”">​</a></h3><h3 id="六四-艮其身-无咎-象曰-艮其身-止诸躬也。" tabindex="-1">六四：艮其身，无咎 象曰：艮其身，止诸躬也。 <a class="header-anchor" href="#六四-艮其身-无咎-象曰-艮其身-止诸躬也。" aria-label="Permalink to “六四：艮其身，无咎 象曰：艮其身，止诸躬也。”">​</a></h3><h3 id="六五-艮其辅-言有序-悔亡-象曰-艮其辅-以中正也。" tabindex="-1">六五：艮其辅，言有序，悔亡 象曰：艮其辅，以中正也。 <a class="header-anchor" href="#六五-艮其辅-言有序-悔亡-象曰-艮其辅-以中正也。" aria-label="Permalink to “六五：艮其辅，言有序，悔亡 象曰：艮其辅，以中正也。”">​</a></h3><p>凡刚柔当位正之象也。孔子赞干之九二龙德而正中，艮之六五曰以中正，何也？曰：艮六五文之误也，当云以正中也。正中者，正得其中，非既正又中也。然则二爻其为不正乎？曰：非谓其然也。中正者，道之贯也，相须而成，相辅而行者也。</p><h3 id="上九-敦艮-吉-象曰-敦艮之吉-以厚终也。" tabindex="-1">上九：敦艮，吉 象曰：敦艮之吉，以厚终也。 <a class="header-anchor" href="#上九-敦艮-吉-象曰-敦艮之吉-以厚终也。" aria-label="Permalink to “上九：敦艮，吉 象曰：敦艮之吉，以厚终也。”">​</a></h3>',11)])])}const f=e(n,[["render",l]]);export{b as __pageData,f as default};
